ex-layout.code:
import math
TAX_RATE = 0.15

def rounded_total(subtotal):
    taxed = subtotal * (1 + TAX_RATE)
    return math.ceil(taxed)

def main():
    print(rounded_total(20))

if __name__ == "__main__":
    main()

